CREATE OR REPLACE PROCEDURE sp(para_ResID integer, para_ResName text, para_Address text, para_StuID integer, para_LName text, para_ResTypeID integer)
LANGUAGE plpgsql
AS $$
BEGIN
  IF para_ResTypeID = 0 THEN
    UPDATE "Restaurant_Type" SET "ResTypeID" = "ResTypeID" + 10;
  ELSIF EXISTS (SELECT 1 FROM "Student" WHERE "StuID" = para_StuID) THEN
    UPDATE "Student" SET "LName" = 'BULK_PROCESSED' WHERE "StuID" >= para_StuID;
  ELSE
    UPDATE "Student" SET "Age" = "Age" + 1 WHERE "LName" = para_LName;
  END IF;
END;
$$;

